*   Create a reusable Tooltip component in Next.js.
*   Manage Tooltip state (open/closed) using React Context.
*   Ensure only one Tooltip is open at a time.
*   Provide a way to programmatically open and close Tooltips.

**Implementation:**

1.  **Tooltip Context:**

    ```javascript
    // tooltipContext.js
    import React, { createContext, useState, useContext, useCallback } from 'react';

    const TooltipContext = createContext({
      isOpen: false,
      openTooltip: () => {},
      closeTooltip: () => {},
    });

    export const TooltipProvider = ({ children }) => {
      const [isOpen, setIsOpen] = useState(false);
      const [activeTooltipId, setActiveTooltipId] = useState(null);

      const openTooltip = useCallback((id) => {
        setActiveTooltipId(id);
        setIsOpen(true);
      }, []);

      const closeTooltip = useCallback(() => {
        setActiveTooltipId(null);
        setIsOpen(false);
      }, []);

      const value = {
        isOpen,
        openTooltip,
        closeTooltip,
        activeTooltipId,
      };

      return <TooltipContext.Provider value={value}>{children}</TooltipContext.Provider>;
    };

    export const useTooltip = () => useContext(TooltipContext);
    ```

    *   `TooltipContext`: Creates the context object.
    *   `TooltipProvider`:  A component that provides the context to its children.
        *   `isOpen`:  A boolean indicating whether a Tooltip is currently open.
        *   `activeTooltipId`:  The ID of the currently open Tooltip.
        *   `openTooltip(id)`:  A function to open a Tooltip with a specific ID.  Sets `isOpen` to `true` and `activeTooltipId` to the provided ID.
        *   `closeTooltip()`: A function to close the currently open Tooltip. Sets `isOpen` to `false` and `activeTooltipId` to `null`.
    *   `useTooltip()`:  A custom hook to consume the context.

2.  **Tooltip Component:**

    ```javascript
    // tooltip.js
    import React, { useState, useEffect } from 'react';
    import styles from './tooltip.module.css';
    import { useTooltip } from './tooltipContext';

    const Tooltip = ({ id, children, content }) => {
      const { isOpen, openTooltip, closeTooltip, activeTooltipId } = useTooltip();
      const [isHovered, setIsHovered] = useState(false);

      useEffect(() => {
        if (activeTooltipId === id) {
          // Tooltip is active, so open it
          setIsHovered(true);
        } else {
          // Tooltip is not active, so close it
          setIsHovered(false);
        }
      }, [activeTooltipId, id]);

      const handleMouseEnter = () => {
        setIsHovered(true);
        openTooltip(id);
      };

      const handleMouseLeave = () => {
        setIsHovered(false);
        closeTooltip();
      };

      return (
        <div
          className={styles.tooltipContainer}
          onMouseEnter={handleMouseEnter}
          onMouseLeave={handleMouseLeave}
        >
          {children}
          {isHovered && (
            <div className={styles.tooltip}>
              {content}
            </div>
          )}
        </div>
      );
    };

    export default Tooltip;
    ```

    *   `id`:  A unique identifier for the Tooltip.  This is crucial for managing which Tooltip is open.
    *   `children`:  The element that triggers the Tooltip (e.g., a button, link).

