/**
 * Packs an array of entities into an ArrayBuffer.
 *
 * @param {Array<Object>} entities An array of entities, where each entity has 'id' (4 bits) and 'size' (3 bits) properties.
 * @returns {ArrayBuffer} An ArrayBuffer containing the packed entities.
 * @throws {Error} If any entity's id or size is out of range.
 */
function packEntities(entities) {
  const totalBits = entities.length * 7; // 4 bits for id + 3 bits for size = 7 bits per entity
  const buffer = new ArrayBuffer(Math.ceil(totalBits / 8));
  const view = new DataView(buffer);
  let bitOffset = 0;

  for (const entity of entities) {
    const id = entity.id;
    const size = entity.size;

    if (id < 0 || id > 15) {
      throw new Error("Entity ID out of range (0-15)");
    }
    if (size < 0 || size > 7) {
      throw new Error("Entity Size out of range (0-7)");
    }

    // Pack ID (4 bits)
    view.setUint8(0, view.getUint8(0) | (id << (bitOffset % 8)));
    bitOffset += 4;

    // Pack Size (3 bits)
    view.setUint8(0, view.getUint8(0) | (size << (bitOffset % 8)));
    bitOffset += 3;
  }

  return buffer;
}

/**
 * Unpacks an ArrayBuffer into an array of entities.
 *
 * @param {ArrayBuffer} buffer The ArrayBuffer containing the packed entities.
 * @returns {Array<Object>} An array of entities, where each entity has 'id' (4 bits) and 'size' (3 bits) properties.
 */
function unpackEntities(buffer) {
  const view = new DataView(buffer);
  const entities = [];
  let bitOffset = 0;

  while (bitOffset < buffer.byteLength * 8) {
    const byteIndex = Math.floor(bitOffset / 8);
    const bitInByte = bitOffset % 8;

    const byte = view.getUint8(byteIndex);
    const id = (byte >> (bitOffset % 8)) & 0xF; // Extract 4 bits for ID
    const size = (byte >> (bitOffset % 8 - 3)) & 0x7; // Extract 3 bits for Size

    entities.push({ id, size });

    bitOffset += 7;
  }

  return entities;
}
```

